files.content:
*,
*::after,
*::before {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

p {
  margin: 0;
}

.question {
  padding: 20px;
  color: #fff;
  background-color: #fd24af;
  list-style: none;
}

.answer {
  padding: 60px 20px;
  color: #fff;
  background-color: #5f0dee;
}

.question::-webkit-details-marker {
  display: none;
}
